// src/components/Header.js
import React, { useState } from 'react';
import { FaMapMarkerAlt, FaPhoneAlt, FaEnvelope } from 'react-icons/fa'; // Importing icons
import Navbar from './Navbar'; // Importing Navbar component
import '../styles.css'; // Assuming styles are in a separate CSS file

const Header = () => {
  const [isNavOpen, setIsNavOpen] = useState(false);

  // Toggle function for the mobile nav
  const toggleNav = () => {
    setIsNavOpen(!isNavOpen);
  };

  return (
    <header className="header-container">
      <div className="header-content">
        <h1 className="header-name">Monwabisi Ndlovu</h1>
        <div className="header-contact">
          <a href="mailto:monwabisindlovu78@gmail.com" className="header-link">
            <FaEnvelope className="header-icon" />
            monwabisindlovu78@gmail.com
          </a>
          <a href="tel:+27849621939" className="header-link">
            <FaPhoneAlt className="header-icon" />
            +27849621939
          </a>
          <span>
            <FaMapMarkerAlt className="header-icon" /> Johannesburg, South Africa
          </span>
        </div>
        {/* Menu button for mobile */}
        <button className="menu-toggle" onClick={toggleNav}>
          ☰
        </button>
      </div>
      
      {/* Navbar component */}
      <Navbar isOpen={isNavOpen} />
    </header>
  );
};

export default Header;
